    explanation: `アルカリシリカ反応の抑制対策は三つある。第一はコンクリート中のアルカリ総量を酸化ナトリウム換算で3.0kg/m3以下に抑える方法、第二は高炉セメントB種やC種、フライアッシュセメントB種やC種など抑制効果のある混合セメントを用いる方法、第三は骨材のアルカリシリカ反応性試験で無害と判定された区分Aの骨材を用いる方法である。JIS A 5308ではこのいずれかを購入者が必ず指定する。単位水量を増やしても反応の抑制にはならず、むしろ乾燥収縮ひび割れを増やして劣化因子の侵入を助長する。

【図解】アルカリシリカ反応の抑制三方策
　方法｜具体的な内容｜考え方
　アルカリ総量規制｜3.0kg/m3以下｜反応物質を減らす
　抑制効果のあるセメント｜高炉B種など｜アルカリを固定
　無害な骨材の使用｜区分Aを使用｜反応性骨材を避ける
　⇒ いずれか一つを購入者が指定する
　⚠ 単位水量を増やすことは抑制対策ではない`,
