    explanation: `ミキサは重力式と強制練り式に大別される。重力式の代表が可傾式ミキサで、回転する混合胴の内部で材料を持ち上げて落下させることで混合する。構造は簡単だが、練混ぜ時間が長く、硬練りや軽量骨材の練混ぜには不向きである。強制練り式にはパン型、二軸、連続式などがあり、羽根が材料を強制的にかき混ぜるため、短時間で均一な練上がりが得られ、硬練りコンクリートや高強度コンクリートにも適する。現在のレディーミクストコンクリート工場では二軸強制練りミキサが主流である。いずれも練混ぜ性能試験に合格したものを用いる。

【図解】ミキサの比較
　方式｜代表例｜練混ぜ時間
　重力式｜可傾式｜長い
　強制練り式｜二軸やパン型｜短い
　⇒ 硬練りや高強度には強制練りが有利
　⚠ 重力式のほうが短時間で均一という記述は誤り`,
    difficulty: 'basic',
