外気温28度は25度を超えるので制限時間は90分である。気温が高いほど水和反応が速く進み、スランプの低下と凝結の進行が早いため、制限時間は短くなる。気温が高いほど長くできるという逆の記述は典型的な誤りである。なお打重ね時間間隔の限度は同じ外気温の境界で150分と120分であり、混同しないよう区別して覚える。

