標準偏差に比べて計算が容易なため、現場での日常管理に用いるxバーR管理図では、ばらつきの管理指標として範囲Rが採用されている。ただし範囲は両端の2個の値だけで決まるため、データ数が多くなると情報の損失が大きくなる。このため組の大きさは通常2から5程度とし、それ以上のデータを扱う場合は標準偏差を用いる管理図に切り替える。

