    question: '超音波法および電磁波レーダ法に関する記述として、適当なものはどれか。',
    choices: [
      { key: 'A', text: '超音波法では、伝播速度が小さいほどコンクリートの品質がよいと判断する。', explanation: '誤り。緻密で健全なコンクリートほど伝播速度は大きくなる。' },
      { key: 'B', text: '超音波法は、伝播速度や伝播時間からコンクリートの品質やひび割れ深さを推定する方法である。', explanation: '正しい。ひび割れ深さの推定にも用いられる代表的な非破壊試験である。' },
      { key: 'C', text: '超音波法は鉄筋の位置とかぶり厚さの測定に最も適した方法である。', explanation: '誤り。鉄筋位置とかぶりの測定には電磁誘導法や電磁波レーダ法を用いる。' },
      { key: 'D', text: '超音波法では、探触子とコンクリート面の間に空隙があっても測定精度は変わらない。', explanation: '誤り。空気層があると超音波が伝わらないため、接触媒質を塗布して密着させる。' },
    ],
    correctKey: 'B',
    explanation: `超音波法は、コンクリート中を伝わる超音波の速度や伝播時間を測定して、品質や内部の欠陥、ひび割れ深さを推定する方法である。緻密で健全なコンクリートほど伝播速度は大きく、空隙やひび割れがあると速度は低下する。探触子とコンクリート面の間に空気層があると超音波が伝わらないので、グリースなどの接触媒質を用いて密着させる。一方、鉄筋の位置やかぶり厚さの測定には、鉄筋による磁束の変化をとらえる電磁誘導法や、電磁波の反射をとらえる電磁波レーダ法が用いられる。電磁波レーダ法は測定が速く、かぶりの分布を面的に把握できる。

【図解】非破壊試験の使い分け
　試験方法｜主な目的
　反発度法｜表層の強度推定
　超音波法｜品質やひび割れ深さの推定
　電磁誘導法｜鉄筋位置とかぶり厚さ
　電磁波レーダ法｜鉄筋位置と内部の状況
　⇒ 目的に応じて方法を選ぶ
　⚠ 伝播速度が小さいほど良いという記述は誤り`,
    difficulty: 'standard',
