    correctKey: 'A',
    explanation: `コンクリート工事の施工計画では、打込み区画の割付け、打継ぎ位置、打込み順序、1日の打込み量、圧送設備の能力、締固め要員の配置、養生方法、型枠の存置期間などを事前に定める。特に打継ぎ位置は構造上の弱点となりやすいため、せん断力の小さい位置に、圧縮力の作用方向と直角になるように計画する。打込み速度は速ければよいというものではなく、締固めが追いつく速度、型枠が耐えられる側圧、打重ね時間間隔を守れる範囲の中で決める。圧送性は配合と配管条件で決まるので、着手前に検討し必要なら試験圧送を行う。

【図解】施工計画で定める主な事項
　項目｜検討の視点
　打込み区画｜打重ね時間間隔を守れるか
　打継ぎ位置｜せん断力の小さい位置か
　打込み速度｜側圧と締固め能力に見合うか
　養生方法｜気温と部材厚に適合するか
　⇒ 事前に決めておくことが品質を決める
　⚠ 打込み速度に上限が不要という記述は誤り`,
    difficulty: 'basic',
