    explanation: `輸送管の呼び寸法は、粗骨材の最大寸法、圧送距離、吐出量から決める。粗骨材の最大寸法が20mmまたは25mmであれば呼び寸法100A、40mmであれば125A以上を標準とする。管径が粗骨材に対して小さいと、骨材どうしがかみ合ってアーチを形成し閉塞する。また管径が小さいほど同じ吐出量に対する流速が上がり、管内圧力損失も大きくなるため、長距離や高所の圧送では大きめの管径を選ぶほうが有利になる。ただし管が太くなると重量が増し、配管の支持や盛替えの手間が増える点も考慮する。

【図解】粗骨材と輸送管の呼び寸法
　粗骨材の最大寸法｜標準的な呼び寸法
　20mmまたは25mm｜100A以上
　40mm｜125A以上
　⇒ 管径が小さいほど圧力損失は大きい
　⚠ 圧送距離と無関係に決めてよいという記述は誤り`,
