【図解】沈みひび割れの機構と対策
　段階｜現象｜対策
　打込み直後｜ブリーディングと沈下｜単位水量の抑制
　沈下の妨げ｜鉄筋直上にひび割れ｜打込み速度の調整
　ブリーディング終了時｜まだ塑性状態｜タンピングや再振動
