同じ気温区分でも早強ポルトランドセメントなら4日、混合セメントB種なら9日となる。気温が15度以上に上がれば普通ポルトランドセメントは5日でよく、5度以上10度未満に下がれば9日必要になる。気温とセメント種類の二つの軸で表を読み取る問題であるから、行と列を取り違えないことが正答の鍵である。冬期の工事では養生期間が長くなり工程に影響するため、早強セメントの採用も検討される。

