    explanation: `かぶり厚さは鉄筋の表面からコンクリート表面までの最短距離であり、三つの重要な役割をもつ。第一は鉄筋の腐食防止で、アルカリ性のコンクリートが鉄筋表面に不動態被膜を保ち、中性化や塩化物イオンの到達を遅らせる。第二は耐火性の確保で、火災時に鉄筋の温度上昇を遅らせる。第三は鉄筋とコンクリートの付着の確保で、かぶりが不足すると付着割裂破壊が生じやすくなる。一方でかぶりが過大になると、ひび割れ幅が大きくなり、かぶりコンクリートの剥落の危険も増すため、最小値だけでなく適正な範囲が重要である。

【図解】かぶり厚さの三つの役割
　役割｜内容
　腐食防止｜中性化や塩化物イオンから鉄筋を守る
　耐火性｜火災時の鉄筋温度上昇を遅らせる
　付着の確保｜付着割裂破壊を防ぐ
　⇒ 過大でも不都合が生じる
　⚠ 鉄筋の中心からの距離とするのは誤り`,
