    explanation: `最小かぶり厚さは、部位と土に接するかどうかによって定められている。土に接しない部分では、屋内のスラブや耐力壁以外の壁で20mm、屋外のそれらで30mm、屋内の柱や梁、耐力壁で30mm、屋外のそれらで40mmが標準である。土に接する部分の柱、梁、床、壁は40mm、基礎は捨てコンクリートの部分を除いて60mmとする。基礎で最も大きいのは、土中の水分や塩分の影響を受けやすく、また施工精度の確保が難しいためである。なお設計かぶり厚さは、施工上の誤差を見込んで最小かぶり厚さに10mmを加えた値とする。

【図解】最小かぶり厚さの目安
　部位｜屋内｜屋外
　スラブや非耐力壁｜20mm｜30mm
　柱や梁や耐力壁｜30mm｜40mm
　土に接する部分｜40mm｜40mm
　基礎｜60mm｜60mm
　⇒ 設計かぶり厚さは最小に10mmを加える
　⚠ 部位によらず一定という記述は誤り`,
