定着長さの倍数は、鉄筋の種類、コンクリートの設計基準強度、フックの有無によって変わる。コンクリートの設計基準強度が大きいほど付着強度も大きくなるので、必要な定着長さは短くなる。またフックを設ければ機械的な抵抗が加わるため、直線定着より短くできる。定着とは、鉄筋に生じる引張力を周囲のコンクリートへの付着によって伝達し、鉄筋が抜け出さないようにすることであり、長さが不足すると抜出しによる破壊が生じる。

